import DOMElements from'./core/dom-elements.js';import Utils from'./core/utils.js';import Storage from'./core/storage.js';import AppState from'./core/app-state.js';import RuleManager from'./managers/rule-manager.js';import CategoryManager from'./managers/category-manager.js';import CommandTester from'./components/command-tester.js';import KeyspaceTester from'./components/keyspace-tester.js';import InteractiveACLBuilder from'./components/interactive-acl-builder.js';import SearchManager from'./components/search-manager.js';import ResizableContainer from'./components/resizable-container.js';import SavedRules from'./components/saved-rules.js';import DragDropPanels from'./components/drag-drop-panels.js';import DragDropTesters from'./components/drag-drop-testers.js';import IntegratedTester from'./components/integrated-tester.js';import EventHandlers from'./handlers/event-handlers.js';const App={async init(){try{DOMElements.init();DragDropPanels.init();DragDropTesters.init();Storage.cleanupDeprecatedKeys();EventHandlers.init();this.restoreUserData();await InteractiveACLBuilder.init();await SearchManager.init();ResizableContainer.init();SavedRules.init();IntegratedTester.initIntegratedTester();if(this.savedRuleToSync){delete this.savedRuleToSync;}}catch(error){console.error('Failed to initialize application:',error);if(DOMElements.commandResults){Utils.showMessage(DOMElements.commandResults,'Failed to initialize application. Please refresh the page.','error');}}},restoreUserData(){try{const savedRule=Storage.loadAclRule();if(savedRule&&DOMElements.aclRuleInput){DOMElements.aclRuleInput.dataset.programmaticUpdate='true';DOMElements.aclRuleInput.value=savedRule;EventHandlers.updateCharacterCounterProgrammatically(DOMElements.aclRuleInput);EventHandlers.updateActionButtonStates();this.savedRuleToSync=savedRule;this.buttonStatesInitialized=true;}
EventHandlers.updateTestButtonStates();const savedVersion=Storage.loadRedisVersion();const versionToggle=document.getElementById('versionToggle');if(versionToggle){const initialVersion=savedVersion||'redis7';AppState.currentVersion=initialVersion;const expectedToggleState=initialVersion==='redis8';if(versionToggle.checked!==expectedToggleState){versionToggle.checked=expectedToggleState;}
if(versionToggle.performVersionSwitch){versionToggle.performVersionSwitch(initialVersion,true);}}}catch(error){console.warn('Failed to restore user data:',error);}}};window.setRule=(rule)=>RuleManager.setRule(rule);window.setRuleAndParse=(rule)=>{const aclRuleTextarea=document.getElementById('aclRule');if(aclRuleTextarea){const currentRule=aclRuleTextarea.value;if(currentRule!==rule){Storage.addToHistory(currentRule);}}
RuleManager.setRule(rule);RuleManager.parseRule();Storage.addToHistory(rule);if(InteractiveACLBuilder.state.isInitialized){InteractiveACLBuilder.syncFromRuleText();}};window.testCommand=()=>CommandTester.testCommand();window.testKeyspace=()=>KeyspaceTester.testKeyspace();window.CategoryManager=CategoryManager;window.syncRuleToInteractive=async()=>{if(window.clearPendingInputOperations){window.clearPendingInputOperations();}
const aclRuleTextarea=document.getElementById('aclRule');if(aclRuleTextarea){const newRule=aclRuleTextarea.value;try{const validation=await Utils.validateACLRule(Utils.normalizeACLRule(newRule));if(!validation.valid){const firstError=validation.errors[0];Utils.showNotification(firstError,'error',5000);return;}}catch(error){Utils.showNotification('Failed to validate ACL rule','error',5000);return;}
Storage.addToHistory(newRule);Storage.saveAclRule(newRule);aclRuleTextarea.dataset.programmaticUpdate='true';const inputEvent=new Event('input',{bubbles:true});aclRuleTextarea.dispatchEvent(inputEvent);}
return InteractiveACLBuilder.syncFromRuleText();};window.getLastGeneratedRule=()=>InteractiveACLBuilder.state?.lastGeneratedRule||'';window.updateInteractiveBuilder=()=>{if(InteractiveACLBuilder.state.isInitialized){InteractiveACLBuilder.loadAllData().then(()=>{InteractiveACLBuilder.scheduleRender(false);});}};window.copyACLRule=()=>{const aclRuleTextarea=document.getElementById('aclRule');if(!aclRuleTextarea){Utils.showNotification('Error: ACL rule text area not found! ❌','error');return;}
let ruleText=aclRuleTextarea.value.trim();if(!ruleText){const committedRule=Storage.loadAclRule();if(committedRule&&committedRule.trim().length>0){ruleText=committedRule.trim();}else{Utils.showNotification('Cannot copy empty ACL rule! ⚠️','warning');return;}}
const isInvalid=!ruleText.includes('+')&&!ruleText.includes('-')&&!ruleText.includes('~');navigator.clipboard.writeText(ruleText).then(()=>{if(isInvalid){Utils.showNotification('Warning: ACL rule may be invalid - copied anyway 📋⚠️','warning');}else{Utils.showNotification('ACL rule copied to clipboard! 📋','success');}}).catch(()=>{try{aclRuleTextarea.select();const successful=document.execCommand('copy');if(successful){if(isInvalid){Utils.showNotification('Warning: ACL rule may be invalid - copied anyway 📋⚠️','warning');}else{Utils.showNotification('ACL rule copied to clipboard! 📋','success');}}else{Utils.showNotification('Failed to copy ACL rule! ❌','error');}}catch(error){Utils.showNotification('Copy operation not supported by browser! ❌','error');}});};window.clearACLRule=()=>{const aclRuleTextarea=document.getElementById('aclRule');if(!aclRuleTextarea){Utils.showNotification('Error: ACL rule text area not found! ❌','error');return;}
const currentRule=aclRuleTextarea.value.trim();const committedRule=Storage.loadAclRule();const hasHistory=Storage.hasHistory();if(!currentRule&&(!committedRule||committedRule.trim().length===0)&&!hasHistory){Utils.showNotification('ACL rule is already empty! 📝','info');return;}
try{aclRuleTextarea.value='';Storage.saveAclRule('');Storage.saveLastGeneratedRule('');Storage.clearHistory();aclRuleTextarea.dataset.programmaticUpdate='true';const inputEvent=new Event('input',{bubbles:true});aclRuleTextarea.dispatchEvent(inputEvent);aclRuleTextarea.focus();aclRuleTextarea.style.height='';const characterCounter=document.getElementById('characterCounter');if(characterCounter){characterCounter.textContent='0/500';characterCounter.classList.remove('near-limit','at-limit');}
RuleManager.hideRedundancyWarnings();RuleManager.parseRule(true);if(InteractiveACLBuilder.state.isInitialized){InteractiveACLBuilder.syncFromRuleText();}
const clearedCurrent=currentRule.length>0;const clearedCommitted=committedRule&&committedRule.trim().length>0;let message='ACL rule and history cleared! 💣';if(!clearedCurrent&&!clearedCommitted&&hasHistory){message='ACL rule history cleared! 💣';}else if(!clearedCurrent&&clearedCommitted){message='Committed ACL rule and history cleared! 💣';}
Utils.showNotification(message,'success');}catch(error){console.error('Error clearing ACL rule:',error);Utils.showNotification('Error occurred while clearing ACL rule! ❌','error');aclRuleTextarea.value=currentRule;}};function checkQuickExamplesScroll(){const content=document.querySelector('.presets-content');if(!content){console.warn('ACL Presets content not found');return;}
const heightDiff=content.scrollHeight-content.clientHeight;const tolerance=12;if(heightDiff>tolerance){content.classList.add('needs-scroll');}else{content.classList.remove('needs-scroll');}}
document.addEventListener('DOMContentLoaded',()=>{window.App=App;window.InteractiveACLBuilder=InteractiveACLBuilder;window.DragDropPanels=DragDropPanels;window.DragDropTesters=DragDropTesters;App.init();setTimeout(checkQuickExamplesScroll,100);const observer=new ResizeObserver(checkQuickExamplesScroll);const aclPanel=document.querySelector('.acl-config-panel');if(aclPanel){observer.observe(aclPanel);}
const textarea=document.getElementById('aclRule');if(textarea){textarea.addEventListener('input',checkQuickExamplesScroll);textarea.addEventListener('mouseup',checkQuickExamplesScroll);observer.observe(textarea);}
const submitBtn=document.getElementById('submitChangesBtn');if(submitBtn){const submitObserver=new MutationObserver(checkQuickExamplesScroll);submitObserver.observe(submitBtn,{attributes:true,attributeFilter:['style']});}
const redundancyWarnings=document.getElementById('redundancyWarnings');if(redundancyWarnings){const warningsObserver=new MutationObserver(checkQuickExamplesScroll);warningsObserver.observe(redundancyWarnings,{attributes:true,attributeFilter:['style'],childList:true,subtree:true});}});window.dismissRedundancyWarnings=()=>{const redundancyWarnings=document.getElementById('redundancyWarnings');if(redundancyWarnings){redundancyWarnings.style.display='none';Utils.showNotification('Redundancy warnings dismissed 👋','info');}};window.resetPanelLayout=()=>{if(window.DragDropPanels&&window.DragDropPanels.state.isInitialized){DragDropPanels.resetToDefault();}else{Utils.showNotification('Panel system not initialized','error');}};window.resetTesterLayout=()=>{if(window.DragDropTesters&&window.DragDropTesters.state.isInitialized){DragDropTesters.resetToDefault();}else{Utils.showNotification('Tester system not initialized','error');}};window.checkQuickExamplesScroll=checkQuickExamplesScroll;if(typeof module!=='undefined'&&module.exports){module.exports={App,RuleManager,CommandTester,CategoryManager,InteractiveACLBuilder,Utils};}